import numpy as np
from gensim.models import Word2Vec
from tokenizers import Tokenizer
import os
from datetime import datetime
from config import TOKENIZER_FILE, OUTPUT_DIR, OUTPUT_MODEL_FILE, TRAINING_PARAMS, MODEL_NAME

# 1. CONFIGURATION OF PATHS
# Must point to files generated by the first script
MODEL_FILE = os.path.join(OUTPUT_DIR, OUTPUT_MODEL_FILE)

# Create logs directory if it doesn't exist
LOGS_DIR = "logs"
if not os.path.exists(LOGS_DIR):
    os.makedirs(LOGS_DIR)
    print(f"Created logs directory: {LOGS_DIR}") 

# 2. LOADING MODEL AND TOKENIZER
print(f"Loading model from: {MODEL_FILE}")
# This is the critical line - loads the entire model state
model = Word2Vec.load(MODEL_FILE)

print(f"Loading tokenizer from: {TOKENIZER_FILE}")
tokenizer = Tokenizer.from_file(TOKENIZER_FILE)

# 3. DEFINING HELPER FUNCTION
def get_word_vector_and_similar(word: str, tokenizer: Tokenizer, model: Word2Vec, topn: int = 20):
    encoding = tokenizer.encode(" " + word + " ") 
    word_tokens = [t.strip() for t in encoding.tokens if t.strip()] # Removing empty tokens
    
    # Removing start/end sequence tokens if added by the tokenizer
    if word_tokens and word_tokens[0] in ['[CLS]', '<s>', '<s>', 'Ġ']:
        word_tokens = word_tokens[1:]
    if word_tokens and word_tokens[-1] in ['[SEP]', '</s>', '</s>']:
        word_tokens = word_tokens[:-1]

    valid_vectors = []
    missing_tokens = []
    
    # 1. Collecting vectors for each token
    for token in word_tokens:
        if token in model.wv:
            # Using token with space (e.g. '_ryż') or without (e.g. 'szlach')
            valid_vectors.append(model.wv[token])
        else:
            # In this place token may be too rare and skipped by MIN_COUNT
            missing_tokens.append(token)

    if not valid_vectors:
        # Code to handle the case when no token has a vector
        if missing_tokens:
            print(f"ERROR: None of the constituent tokens ('{word_tokens}') are in the dictionary (Check MIN_COUNT).")
        else:
            print(f"ERROR: Word '{word}' was not processed into vectors (check tokenization).")
        return None, None

    # 2. Averaging vectors
    # The vector for the whole word is the average of the vectors of its constituent tokens
    word_vector = np.mean(valid_vectors, axis=0)

    # 3. Finding the most similar tokens
    similar_words = model.wv.most_similar(
        positive=[word_vector],
        topn=topn
    )
    
    return word_vector, similar_words

# 4. MAIN TESTING
words_to_test = ['wojsko', 'szlachta', 'król']

# Create log file with timestamp
timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
log_filename = f"{MODEL_NAME}-results-{timestamp}.log"
log_filepath = os.path.join(LOGS_DIR, log_filename)

print("\n--- Starting model testing ---")
print(f"Results will be logged to: {log_filepath}")

# Open log file for writing
with open(log_filepath, 'w', encoding='utf-8') as log_file:
    # Write header and configuration
    log_file.write("=" * 80 + "\n")
    log_file.write(f"Word2Vec CBOW Model Inference Results\n")
    log_file.write(f"Generated at: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
    log_file.write("=" * 80 + "\n\n")
    
    # Write model and tokenizer info
    log_file.write("MODEL INFORMATION:\n")
    log_file.write("-" * 80 + "\n")
    log_file.write(f"Model file: {MODEL_FILE}\n")
    log_file.write(f"Tokenizer file: {TOKENIZER_FILE}\n")
    log_file.write("\n")
    
    # Write training parameters
    log_file.write("TRAINING PARAMETERS:\n")
    log_file.write("-" * 80 + "\n")
    for param, value in TRAINING_PARAMS.items():
        log_file.write(f"{param}: {value}\n")
    log_file.write("\n")
    
    # Write test results
    log_file.write("TEST RESULTS:\n")
    log_file.write("-" * 80 + "\n\n")
    
    for word in words_to_test:
        word_vector, similar = get_word_vector_and_similar(word, tokenizer, model)
        if word_vector is not None:
            # Write to console
            print(f"\n 5 most similar words to {word}. (average token vectors {tokenizer.encode(word).tokens}):")
            # Show word vector (first 5 elements)
            print(f"  > Word vector (start): {word_vector[:5]}...")
            # Write to log
            log_file.write(f" 5 most similar words to {word}. (average token vectors {tokenizer.encode(word).tokens}):\n")
            log_file.write(f"  > Word vector (start): {word_vector[:5]}...\n")

            for token, similarity in similar[:5]: # Show top 5
                result_line = f"  - {token}: {similarity:.4f}"
                # Write to console
                print(result_line)
                # Write to log
                log_file.write(result_line + "\n")
            
            log_file.write("\n")

    # 5. MATHEMATICAL PATTERN VERIFICATION (Vector analogy)

    tokens_analogy = ['dziecko', 'kobieta']

    # Using average vector for tokens
    if tokens_analogy[0] in model.wv and tokens_analogy[1] in model.wv:
        similar_to_combined = model.wv.most_similar(
            positive=tokens_analogy,
            topn=10
        )

        # Write to console
        print(f"\n10 most similar tokens to the combination of tokens: {tokens_analogy}")
        # Write to log
        log_file.write(f"10 most similar tokens to the combination of tokens: {tokens_analogy}\n")
        for token, similarity in similar_to_combined:
            result_line = f"  - {token}: {similarity:.4f}"
            # Write to console
            print(result_line)
            # Write to log
            log_file.write(result_line + "\n")
    else:
        # Write to console
        print(f"\nWarning: At least one of the tokens '{tokens_analogy}' is not in the dictionary. Skipping analogy.")
        # Write to log
        log_file.write(f"Warning: At least one of the tokens '{tokens_analogy}' is not in the dictionary. Skipping analogy.\n")
        log_file.write("=" * 80 + "\n")
        log_file.write("End of results\n")

    print(f"\nResults saved to: {log_filepath}")